var list = reports.ToList();
if (!list.Any()) return WorkOrderStatus.InProgress;
if (list.Any(r => r.Status == ReportStatus.Cancelled)) return WorkOrderStatus.InProgress;
return list.All(r => r.Status == ReportStatus.Sent)
  ? WorkOrderStatus.Worked
  : WorkOrderStatus.InProgress;

INSERT INTO SupplierPermissions (SupplierId, PermissionId)
SELECT @SupplierId, @PermissionId
WHERE NOT EXISTS (
  SELECT 1 FROM SupplierPermissions
  WHERE SupplierId = @SupplierId AND PermissionId = @PermissionId
);

